var a = [1, 2, 2, 2, 3, 5];
var low = 0;
var high = a.length - 1;
var index = -1;
while (low <= high) {
  var mid = Math.floor((low + high) / 2);
  if (a[mid] === 2) {
    index = mid;
    high = mid - 1;
  } else if (a[mid] < 2) {
    low = mid + 1;
  } else {
    high = mid - 1;
  }
}
console.log(index);
